    const out={}; for(const line of raw.split(/\r?\n/)){const m=line.match(/^\s*(\d{1,3})\s*[,;:\t\s]\s*([ABCD])\b/i);if(m&&Number(m[1])>=1&&Number(m[1])<=100)out[Number(m[1])]=m[2].toUpperCase()} return normalizeAnswerKey(out);
