  function omrCanvasScore(img,needPage){return new Promise((resolve,reject)=>{const im=new Image();im.onload=()=>{try{const W=794,H=1123,cv=document.createElement('canvas');cv.width=W;cv.height=H;const c=cv.getContext('2d',{willReadFrequently:true});c.drawImage(im,0,0,W,H);const d=c.getImageData(0,0,W,H).data;let sum=0,sum2=0,count=0,grad=0;for(let y=1;y<H;y+=5){for(let x=1;x<W;x+=5){const idx=(y*W+x)*4, r=d[idx],g=d[idx+1],b=d[idx+2],v=(r+g+b)/3;sum+=v;sum2+=v*v;count++;if(x>0){const p=d[((y)*W+(x-1))*4];grad+=Math.abs(v-p)}}}const mean=sum/count,variance=Math.max(0,sum2/count-mean*mean),sharp=Math.min(100,Math.round((Math.sqrt(variance)*1.8)+(grad/count)*2));resolve({cv,quality:{mean,variance,sharp}})}catch(e){reject(e)}};im.onerror=reject;im.src=URL.createObjectURL(imgFileGlobal);});}
  // Improved extractor with center-zone measurements and adaptive row confidence.
  async function extractOMRV8(file,page){
    const url=URL.createObjectURL(file), img=new Image();
    await new Promise((res,rej)=>{img.onload=res;img.onerror=rej;img.src=url});
    URL.revokeObjectURL(url);
    const W=794,H=1123,cv=document.createElement('canvas');cv.width=W;cv.height=H;
    const ctx=cv.getContext('2d',{willReadFrequently:true});ctx.drawImage(img,0,0,W,H);const px=ctx.getImageData(0,0,W,H).data;
    const L=(x,y)=>{x=Math.max(0,Math.min(W-1,Math.round(x)));y=Math.max(0,Math.min(H-1,Math.round(y)));const k=(y*W+x)*4;return (px[k]+px[k+1]+px[k+2])/3};
    const optionXs=[430,485,540,595], firstY=250, rowStep=15;
    const answers={},uncertain=[],scores=[], allVals=[];
    const disk=(cx,cy,r)=>{let sum=0,n=0;for(let yy=-r;yy<=r;yy++)for(let xx=-r;xx<=r;xx++)if(xx*xx+yy*yy<=r*r){sum+=L(cx+xx,cy+yy);n++}return sum/n};
    for(let i=0;i<50;i++){
      const q=page===1?i+1:i+51,cy=firstY+i*rowStep;
      const vals=optionXs.map(cx=>{const inner=disk(cx,cy,4.5),outer=(disk(cx,cy,7)-inner*25/(Math.PI*7*7))/(1-25/(Math.PI*7*7));return Math.max(0,outer-inner)});
      const sorted=[...vals].sort((a,b)=>b-a),best=sorted[0],second=sorted[1],margin=best-second;
      allVals.push(...vals);scores.push({q,values:vals,margin,best});
      // Scores are contrast (ring minus center); filled bubbles have substantially higher contrast.
      if(best>=12 && margin>=3.5) answers[q]=['A','B','C','D'][vals.indexOf(best)];
      else uncertain.push({q,reason:best<12?'low-contrast':'low-margin',scores:vals});
    }
    const mean=allVals.reduce((a,b)=>a+b,0)/Math.max(1,allVals.length),variance=allVals.reduce((a,b)=>a+(b-mean)**2,0)/Math.max(1,allVals.length);
    return {answers,uncertain,scores,quality:{method:'template-calibrated center-v-ring',resolution:`${img.naturalWidth}×${img.naturalHeight}`,contrastMean:Number(mean.toFixed(2)),contrastVariance:Number(variance.toFixed(2))},page};
  }
