  function buildAIContext(){const s=studyState(),e=engineState();return{version:V8_VERSION,view:state.view,pyqCount:state.pyq.length,study:{today:study14().at(-1)?.mins||0,week:study14().slice(-7).reduce((a,b)=>a+b.mins,0),active:s.active?.subject||null,sessions:s.sessions.slice(0,20)},mock:{active:e.active,run:e.run?.state||null},filters:state.filters||{},features:(state.features||[]).slice(0,180).map(x=>x.name||x.feature||x.title).filter(Boolean),lastResult:(evalState().queue||[]).slice(-1)[0]?.result||null}}
  async function readEventStream(resp,onChunk){if(!resp.body)return;const reader=resp.body.getReader(),dec=new TextDecoder();let buf='';while(true){const {value,done}=await reader.read();if(done)break;buf+=dec.decode(value,{stream:true});const lines=buf.split(/\r?\n/);buf=lines.pop()||'';for(const ln of lines){const line=ln.replace(/^data:\s*/,'').trim();if(!line||line==='[DONE]')continue;try{const j=JSON.parse(line);onChunk(j)}catch{}}}}
  function extractTextFlexible(x){const found=[];const walk=v=>{if(!v)return;if(typeof v==='string'){if(v.length>2)found.push(v);return}if(Array.isArray(v)){v.forEach(walk);return}if(typeof v==='object'){for(const [k,val] of Object.entries(v)){if(['text','delta','content','output_text'].includes(k))walk(val);else if(k==='outputs'||k==='choices'||k==='content')walk(val)}}};walk(x);return found.find(t=>/\S/.test(t))||''}
  async function runMistralV8(){const prompt=document.getElementById('v8AIPrompt')?.value.trim();if(!prompt)return toast('Enter a prompt.','error');const live=document.getElementById('v8AILive');const web=!!document.getElementById('v8AIWeb')?.checked;const body={prompt,web,context:buildAIContext(),conversationId:LS.getItem('precision-mistral-conversation')||null};live.textContent='Connecting to Mistral Small 4…';try{const r=await fetch('/api/ai',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});if(!r.ok){let msg='AI backend '+r.status;try{const j=await r.json();msg=j?.error||msg}catch{}throw new Error(msg)};let text='';await readEventStream(r,j=>{const cid=j?.conversation_id||j?.conversationId||j?.conversation?.id||j?.data?.conversation_id||j?.data?.conversationId;if(cid)LS.setItem('precision-mistral-conversation',cid);const part=extractTextFlexible(j);if(part){text+=text&&part.startsWith(text)?part:text+part;live.textContent=text}});if(!text){const tx=await r.text().catch(()=>"");text=tx||'No response text.';live.textContent=text}pushAIHistory({at:new Date().toISOString(),mode:'MISTRAL-SMALL-4',prompt,reply:text});syncLocalEnvelope();toast('AI response received.','info')}catch(err){live.textContent='AI error: '+err.message;toast(err.message,'error')}}
  function viewAIV8(){const hist=gHistory().slice(0,16);return `<div class="view-head"><div><div class="eyebrow">AI / COMMAND + ANALYSIS</div><div class="title">Mistral Small 4 • Personal AI Agent</div><div class="desc">Realtime responses go through your deployed server endpoint. API keys are never bundled into this ZIP.</div></div>${badge('REAL-TIME')}</div><div class="card"><div class="split"><h3 class="section-title">Live AI Console</h3>${badge('MISTRAL SMALL 4')}</div><textarea id="v8AIPrompt" class="ai-input" placeholder="Ask: analyse my study balance, open OMR, explain this PYQ, build a plan, inspect my weak areas…"></textarea><div class="actions"><label class="checkline"><input type="checkbox" id="v8AIWeb" checked> Enable web research</label><button class="btn primary" data-v8-action="ai-run">Run in realtime</button><button class="btn" data-v8-action="ai-clear">Clear</button></div><div id="v8AIStatus" class="notice">Endpoint: <span class="mono">/api/ai</span> • model: <span class="mono">mistral-small-latest</span></div><pre id="v8AILive" class="ai-stream">Ready.</pre></div><div class="grid g2" style="margin-top:14px"><div class="card"><div class="split"><h3 class="section-title">10 AI actions</h3>${badge('ALL TABS')}</div><div class="v8-chip-grid">${['Navigate any tab','Explain selected PYQ','Study-time audit','Subject balance analysis','Mock result summary','Weak-area diagnosis','Plan next study block','OMR/key audit','Research current topic','Write/export analysis'].map((x,i)=>`<span class="v8-track-chip">${String(i+1).padStart(2,'0')} • ${x}</span>`).join('')}</div></div><div class="card"><div class="split"><h3 class="section-title">Recent AI research</h3>${badge(String(hist.length))}</div><div class="v8-ai-history">${hist.map(x=>`<div><b>${esc8(x.mode||'AI')}</b><span>${esc8(x.prompt)}</span><small>${esc8(String(x.reply||'').slice(0,280))}</small></div>`).join('')||'<div class="empty">No AI research saved yet.</div>'}</div></div></div>`}
  function viewHealthV8(){const h=loadLocalJSON('precision-health-v8',{hydration:0,breaks:0,eyes:0,posture:0,energy:3,mood:3,sleepHours:'',focus:3,distractions:0,note:''});const fields=[['hydration','Water check'],['breaks','Breaks taken'],['eyes','20-20-20 eye rests'],['posture','Posture resets']];return `<div class="view-head"><div><div class="eyebrow">STUDY HEALTH / HABITS</div><div class="title">Study Health Dashboard</div><div class="desc">Simple self-tracking for study quality; no medical judgement.</div></div>${badge('10 SIGNALS')}</div><div class="grid g4">${metric('ENERGY',h.energy+'/5','your check-in','green')}${metric('MOOD',h.mood+'/5','your check-in','purple')}${metric('FOCUS',h.focus+'/5','self-rated','cyan')}${metric('DISTRACTIONS',h.distractions,'logged today','amber')}</div><div class="grid g2" style="margin-top:14px"><div class="card"><h3 class="section-title">Habit counters</h3><div class="v8-health-grid">${fields.map(([id,lab])=>`<label><span>${lab}</span><input id="v8h_${id}" type="number" min="0" value="${Number(h[id]||0)}"></label>`).join('')}<label><span>Sleep hours note</span><input id="v8h_sleepHours" value="${esc8(h.sleepHours||'')}"></label><label><span>Energy 1–5</span><input id="v8h_energy" type="number" min="1" max="5" value="${h.energy}"></label><label><span>Mood 1–5</span><input id="v8h_mood" type="number" min="1" max="5" value="${h.mood}"></label><label><span>Focus 1–5</span><input id="v8h_focus" type="number" min="1" max="5" value="${h.focus}"></label><label><span>Distractions</span><input id="v8h_distractions" type="number" min="0" value="${h.distractions}"></label></div><textarea id="v8h_note" class="ai-input" style="margin-top:10px" placeholder="Optional note">${esc8(h.note||'')}</textarea><div class="actions"><button class="btn primary" data-v8-action="health-save">Save today</button><button class="btn" data-v8-action="health-reset">Reset counters</button></div></div><div class="card"><h3 class="section-title">Useful 10-feature checklist</h3><div class="v8-check-grid">${['Hydration check','Break count','Eye-rest count','Posture reset count','Energy score','Mood score','Sleep note','Focus score','Distraction count','Daily note'].map((x,i)=>`<span><b>${i+1}</b>${x}</span>`).join('')}</div><div class="notice" style="margin-top:12px">These are study-habit signals, not health diagnoses or treatment guidance.</div></div></div>`}
